<?php
namespace Tests\Unit;
use App\Models\CreatorProfile; use App\Models\DigitalMedia; use App\Models\User; use PHPUnit\Framework\TestCase;
class MarketplaceRulesTest extends TestCase { public function test_unapproved_creator_cannot_sell(): void { $creator=new CreatorProfile(['status'=>'pending']); $creator->setRelation('user',new User(['account_status'=>'active'])); $media=new DigitalMedia(['status'=>'published','visibility'=>'paid','price_minor'=>1200]); $media->setRelation('creatorProfile',$creator); self::assertFalse($media->isPurchasable()); } public function test_approved_creator_can_sell_published_paid_media(): void { $creator=new CreatorProfile(['status'=>'approved']); $creator->setRelation('user',new User(['account_status'=>'active'])); $media=new DigitalMedia(['status'=>'published','visibility'=>'paid','price_minor'=>1200]); $media->setRelation('creatorProfile',$creator); self::assertTrue($media->isPurchasable()); } public function test_free_media_is_not_a_paid_purchase(): void { $creator=new CreatorProfile(['status'=>'approved']); $creator->setRelation('user',new User(['account_status'=>'active'])); $media=new DigitalMedia(['status'=>'published','visibility'=>'free','price_minor'=>null]); $media->setRelation('creatorProfile',$creator); self::assertFalse($media->isPurchasable()); } }